## Pydantic Validation Best Practices

```python
from typing import Optional, List
from pydantic import (
    BaseModel,
    Field,
    field_validator,
    model_validator,
    EmailStr,
    HttpUrl
)
from datetime import date, datetime
import re

class UserCreate(BaseModel):
    """User creation model with comprehensive validation."""

    email: EmailStr
    password: str = Field(..., min_length=8, max_length=128)
    username: str = Field(..., min_length=3, max_length=50, pattern=r'^[a-zA-Z0-9_]+$')
    full_name: str = Field(..., min_length=1, max_length=100)
    birth_date: Optional[date] = None
    website: Optional[HttpUrl] = None
    tags: List[str] = Field(default_factory=list, max_length=10)

    @field_validator('password')
    @classmethod
    def validate_password(cls, v: str) -> str:
        """Validate password strength."""
        if not re.search(r'[A-Z]', v):
            raise ValueError('Password must contain uppercase letter')
        if not re.search(r'[a-z]', v):
            raise ValueError('Password must contain lowercase letter')
        if not re.search(r'\d', v):
            raise ValueError('Password must contain digit')
        if not re.search(r'[!@#$%^&*(),.?":{}|<>]', v):
            raise ValueError('Password must contain special character')
        return v

    @field_validator('birth_date')
    @classmethod
    def validate_birth_date(cls, v: Optional[date]) -> Optional[date]:
        """Validate birth date is in the past and user is at least 13."""
        if v is None:
            return v
        today = date.today()
        if v >= today:
            raise ValueError('Birth date must be in the past')
        age = (today - v).days // 365
        if age < 13:
            raise ValueError('User must be at least 13 years old')
        return v

    @field_validator('tags', mode='before')
    @classmethod
    def validate_tags(cls, v):
        """Normalize and validate tags."""
        if isinstance(v, str):
            v = [t.strip() for t in v.split(',')]
        return [t.lower().strip() for t in v if t.strip()]

    @model_validator(mode='after')
    def validate_model(self):
        """Cross-field validation."""
        if self.username.lower() in self.password.lower():
            raise ValueError('Password cannot contain username')
        return self
